/*
 * What the stage's modules share: the host forum.js handed over, the effects,
 * the stage element, pending timers, and small DOM and text helpers.
 */

/** Set by open() before anything else reads it. */
export const st = {
  host: null,
  fx: null,
  fxAll: null,
  root: null,
  timers: [],
  ticker: 0,
  current: null
};
export const later = (fn, ms) => st.timers.push(window.setTimeout(fn, ms));
export const $ = s => st.root.querySelector(s);
export const $$ = s => Array.from(st.root.querySelectorAll(s));
export const lamps = () => $$('.Piece .Lamp');
export const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;'
})[c]);
export const t = (key, params) => esc(st.host.t(key, params));
export const calm = () => matchMedia('(prefers-reduced-motion: reduce)').matches || !st.host.effects() || !!st.host.quiet;
export function focusTitle() {
  const el = st.root && st.root.querySelector('#ffTitle');
  if (el && el.offsetParent) el.focus({
    preventScroll: true
  });
}
flarum.reg.add('ernestdefoe-fanfare', 'forum/stage/state', { st: st,later: later,lamps: lamps,esc: esc,t: t,calm: calm,focusTitle: focusTitle, });